// ===== CALLBACK MAYAR — hardened (Lentera) =====
// Token wajib, event payment.received + status PAID, anti-duplikat transaksi.
const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const headers = raw.headers || {};

// --- 1. Verifikasi token callback Mayar (wajib, fail-closed) ---
const expectedToken = $env.MAYAR_CALLBACK_TOKEN;
const gotToken = headers['x-callback-token'] || headers['X-Callback-Token'] || headers['x-callback-token'.toLowerCase()] || '';
if (!expectedToken) throw new Error('Callback: MAYAR_CALLBACK_TOKEN belum diset di n8n env');
if (String(gotToken) !== String(expectedToken)) throw new Error('Callback Mayar ditolak: token tidak valid');

// --- 2. Parse payload ---
const event = String(body.event || '');
const data = body.data || {};
const s = data.status;
const statusPaid = s === true || s === 'true' || s === 'PAID' || s === 'paid' || s === 'SUCCESS' || s === 'success';
const txPaid = data.transactionStatus === 'paid' || data.transactionStatus === 'PAID';
const reference = String(data.transactionId || data.id || body.id || '').trim();
const email = String(data.customerEmail || '').trim().toLowerCase();

// --- 3. Hanya event payment.received + PAID yang onboarding ---
const isPaid = event === 'payment.received' && (statusPaid || txPaid);
if (isPaid && (!reference || !email)) {
  throw new Error('Callback payment.received tidak lengkap: reference & email wajib');
}

// --- 4. Cek duplikat transaksi (lihat leads.notes) ---
let duplicate = false;
if (isPaid) {
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qxzvmnbhplgmspdxdbmg.supabase.co/rest/v1/leads?select=email,notes&email=eq.' + encodeURIComponent(email) + '&order=created_at.desc&limit=1',
    headers: { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY },
    json: true, timeout: 10000
  });
  const lead = Array.isArray(rows) && rows.length ? rows[0] : null;
  const refs = String(lead && lead.notes || '').match(/payment_ref:([^\s]+)/g) || [];
  duplicate = refs.some((e) => e.slice('payment_ref:'.length) === reference);
}

return {
  json: {
    valid: true, event, isPaid: isPaid && !duplicate, duplicate, reference,
    amount: Number(data.amount || 0),
    customerName: data.customerName || '',
    customerEmail: email,
    customerMobile: data.customerMobile || '',
    productId: data.productId || '',
    productName: data.productName || '',
    pixelFbp: data.pixelFbp || '', pixelFbc: data.pixelFbc || '',
    raw: JSON.stringify(raw).slice(0, 2000)
  }
};

// Ambil discord_id lead + pastikan tier lifetime dari productId
const TIER_BY_PRODUCT_ID = {
  'd8927ccd-4323-4500-b4f3-2f0e4f82acd1': 'yearly',
  '56284414-f48b-47b9-af79-74d2b0f4b2dd': 'lifetime',
  'cd838d9a-d47b-412a-93bd-b794f671c7e0': 'early-bird',
  '6aa86b90-ced1-4607-91b4-c773f19154c1': 'regular',
  'ed110ea7-d8ef-4b22-9d06-ce0447986293': 'early-bird',
  '11cf4e1f-798a-4158-ab98-36c97a308ac2': 'regular'
};
const p = $input.first().json;
const email = String(p.customerEmail || '').trim().toLowerCase();

let discordId = '';
let leadNotes = '';
if (email) {
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qxzvmnbhplgmspdxdbmg.supabase.co/rest/v1/leads?select=discord_id&email=eq.' + encodeURIComponent(email) + '&order=created_at.desc&limit=1',
    headers: { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY },
    json: true, timeout: 10000
  });
  const lead = Array.isArray(rows) && rows.length ? rows[0] : null;
  discordId = String(lead && lead.discord_id || '').trim();
  leadNotes = String(lead && lead.notes || '').trim();
}

// tier dari productId dulu; fallback deteksi nama produk lifetime
let tier = 'yearly';
const noteTier = String(leadNotes).match(/tier:(early-bird|regular|yearly|lifetime)/i);
if (noteTier) tier = noteTier[1].toLowerCase();
else tier = TIER_BY_PRODUCT_ID[String(p.productId || '').toLowerCase()] || tier;
if (!noteTier) {
  const txt = [p.productName || '', p.raw || ''].join(' ').toLowerCase();
  if (/life[\s-]?time|lifetime/.test(txt)) tier = 'lifetime';
}

return {
  json: {
    email: email,
    name: p.customerName || '',
    mobile: p.customerMobile || '',
    tier, discordId, notes: leadNotes,
    amount: p.amount || 0,
    reference: p.reference || '',
    tierSource: TIER_BY_PRODUCT_ID[String(p.productId || '').toLowerCase()] ? 'productId' : 'productName'
  }
};

// \u2728 EMAIL AKSES \u2014 dikirim via Resend setelah /api/provision-lms mengembalikan kredensial.
// Token node ini berisi respons API, BUKAN payload Mayar \u2014 jadi nama/email harus
// diambil dari node Parse, password dari respons provisioning.
const parsed = $('Code: Parse Mayar Callback').first().json;
const prep = $('Code: Siapkan Data LMS').first().json;
const prov = $input.first().json || {};

const RESEND_FROM = $env.RESEND_FROM || 'XindeLabs <no-reply@xindelabs.web.id>';
const LMS_URL = String($env.NEXT_PUBLIC_LMS_URL || 'https://xindelabs-workshop.vercel.app').replace(/\/+$/, '');
const DISCORD_URL = $env.DISCORD_INVITE_URL || 'https://discord.gg/JXZWZZRsre';

const provisioned = prov.ok === true && !!prov.lms_password;
if (!provisioned) throw new Error('Provisioning LMS gagal: kredensial tidak tersedia');
const nama = String(parsed.customerName || '').trim();
const email = String(parsed.customerEmail || prov.email || '').trim().toLowerCase();
const TIER_LABELS = { lifetime: 'Life-Time', yearly: 'Tahunan', 'early-bird': 'Early Bird', regular: 'Reguler' };
const tierLabel = TIER_LABELS[prep.tier] || 'Reguler';
const rupiah = (n) => 'Rp ' + Number(n || 0).toLocaleString('id-ID');

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function row(label, value, mono) {
  return '<tr><td style="padding:8px 0;color:#6b7280;font-size:14px;width:140px;vertical-align:top;">' + label + '</td>' +
    '<td style="padding:8px 0;color:#111827;font-size:14px;' +
    (mono ? 'font-family:ui-monospace,SFMono-Regular,Menlo,monospace;' : '') + '">' + value + '</td></tr>';
}

const kredensial = provisioned
  ? '<div style="margin:24px 0;padding:20px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:12px;">' +
      '<p style="margin:0 0 12px;font-weight:700;color:#065f46;font-size:16px;">\u2728 Akun Workshop lo sudah aktif</p>' +
      '<table style="width:100%;border-collapse:collapse;">' +
        row('Login', '<a href="' + LMS_URL + '/login" style="color:#047857;">' + LMS_URL + '/login</a>', true) +
        row('Email', esc(prov.email || email), true) +
        row('Password', esc(prov.lms_password), true) +
      '</table>' +
      '<p style="margin:14px 0 0;color:#065f46;font-size:13px;">Masuk pakai email + password di atas. Jangan share password ini ke siapa pun.</p>' +
    '</div>'
  : '<div style="margin:24px 0;padding:20px;background:#fef2f2;border:1px solid #fecaca;border-radius:12px;">' +
      '<p style="margin:0 0 8px;font-weight:700;color:#991b1b;font-size:16px;">Pembayaran diterima, akun sedang disiapkan</p>' +
      '<p style="margin:0;color:#7f1d1d;font-size:14px;">Sistem kami gagal membuat akses otomatis. Balas email ini supaya admin bisa mengaktifkan akun lo secara manual.</p>' +
    '</div>';

const html =
  '<div style="font-family:ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:560px;margin:0 auto;padding:24px;color:#111827;">' +
  '<h1 style="font-size:20px;margin:0 0 4px;">Pembayaran diterima</h1>' +
  '<p style="margin:0 0 20px;color:#6b7280;font-size:14px;">Terima kasih' + (nama ? ', ' + esc(nama) : '') + '.</p>' +
  '<table style="width:100%;border-collapse:collapse;">' +
    row('Produk', 'Kelas XindeLabs \u2014 ' + tierLabel) +
    row('Dibayar', rupiah(parsed.amount), true) +
    row('Referensi', esc(parsed.reference || '-'), true) +
  '</table>' +
  kredensial +
  '<p style="margin:24px 0 6px;font-weight:600;font-size:15px;">Join komunitas Discord</p>' +
  '<p style="margin:0;font-size:14px;color:#4b5563;">Diskusi, sharing prompt, dan sesi use-case bareng member lain: <a href="' + DISCORD_URL + '" style="color:#047857;">' + DISCORD_URL + '</a></p>' +
  '<p style="margin:28px 0 0;color:#9ca3af;font-size:12px;">Email ini dikirim otomatis. Balas email ini kalau ada kendala.</p>' +
'</div>';

return {
  json: {
    from: RESEND_FROM,
    to: [email],
    subject: provisioned ? 'Akses Kelas XindeLabs lo sudah aktif' : 'Pembayaran diterima \u2014 akses sedang disiapkan',
    html: html,
    lms_password: provisioned ? prov.lms_password : '',
    needs_manual: !provisioned
  }
};

// Log callback yang bukan PAID (debug)
const payment = $input.first().json;
return {
  json: {
    log: 'CALLBACK BUKAN PAID',
    status: payment.status,
    reference: payment.reference,
    amount: payment.amount
  }
};

// ===== DISCORD: auto-assign role member =====
// Tier lifetime -> role 'Life Time', yearly -> 'Connect Circle'
const DISCORD_TOKEN = $env.DISCORD_BOT_TOKEN;
const GUILD_ID = '1260441398449143948';
const ROLES = {
  lifetime:    '1538779341368860673',  // Inner Circle
  'early-bird': '1260443455558254602', // AI Agent Circle (kelas)
  regular:     '1260443455558254602',  // AI Agent Circle (kelas)
  yearly:      '1260443523870621736'   // Connect Circle
};

const prep = $('Code: Siapkan Data LMS').first().json;
const discordId = String(prep.discordId || '').trim();
const tier = String(prep.tier || 'yearly').toLowerCase();
const roleId = ROLES[tier] || ROLES.yearly;

const out = { ok: false, discordId, tier, roleId, step: '', error: '' };

if (!DISCORD_TOKEN) {
  out.step = 'skip'; out.error = 'DISCORD_BOT_TOKEN belum diset';
  return { json: out };
}
if (!discordId || !/^\d{17,20}$/.test(discordId)) {
  out.step = 'skip'; out.error = 'discord_id tidak valid/kosong: ' + JSON.stringify(discordId);
  return { json: out };
}

const base = 'https://discord.com/api/v10';
const auth = { Authorization: 'Bot ' + DISCORD_TOKEN, 'Content-Type': 'application/json' };

// 1. Cari member guild by user id (butuh Server Members Intent)
out.step = 'lookup';
const mem = await this.helpers.httpRequest({
  method: 'GET',
  url: `${base}/guilds/${GUILD_ID}/members/${discordId}`,
  headers: auth,
  json: true,
  timeout: 10000
}).catch((e) => { out.error = 'lookup gagal: ' + (e.message || e); return null; });

if (!mem) {
  out.step = 'lookup-fail'; out.error = 'User belum join server (invite link via email). Discord ID: ' + discordId;
  return { json: out };
}

// 2. Assign role
out.step = 'assign-role';
const r = await this.helpers.httpRequest({
  method: 'PUT',
  url: `${base}/guilds/${GUILD_ID}/members/${discordId}/roles/${roleId}`,
  headers: auth,
  timeout: 10000,
  returnFullResponse: true
}).catch((e) => { out.error = 'assign role gagal: ' + (e.message || e); return null; });

if (!r || (r.statusCode && r.statusCode >= 400)) {
  out.step = 'assign-fail';
  out.error = 'assign role HTTP ' + (r ? r.statusCode : 'null');
  return { json: out };
}

out.ok = true;
out.step = 'done';
out.error = '';
return { json: out };
